# NOT EXECUTED. Inspection example, not a strict whole-word adapter.
from slugify import smart_truncate

def inspect(text, assumed_limit=160):
    return {
        'slicing_baseline': text[:assumed_limit],
        'existing_mechanism': smart_truncate(text, max_length=assumed_limit,
            word_boundary=True, save_order=True),
    }
